async function signIn(event){event.preventDefault();if(!supabaseClient)return;setAdminFeedback('Entrando...');const email=document.querySelector('#admin-email').value.trim();const password=document.querySelector('#admin-password').value;const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error){setAdminFeedback('Não foi possível entrar. Confira o e-mail e a senha.',true);return;}if(!hasAdminAccess(data.user)){await supabaseClient.auth.signOut();adminUser=null;updateAdminPanel();setAdminFeedback('Esta conta não tem permissão de acesso administrativo.',true);return;}adminUser=data.user;updateAdminPanel();setAdminFeedback('Acesso autorizado.');await loadRemotePoints();}
