async function decidePointSuggestion(id,decision,button){
  if(!isSiteAdmin()){setAdminFeedback('Somente administradores podem decidir indicações.',true);return;}
  let decisionNote=null;
  if(decision==='rejected'){
    const entered=window.prompt('Informe o motivo da rejeição (obrigatório, até 500 caracteres):');
    if(entered===null){setAdminFeedback('Rejeição cancelada. A indicação continua pendente.');return;}
    decisionNote=entered.trim();
    if(!decisionNote){setAdminFeedback('Informe um motivo para rejeitar a indicação.',true);return;}
    if(decisionNote.length>500){setAdminFeedback('O motivo deve ter no máximo 500 caracteres.',true);return;}
  }
  button.disabled=true;
  const {data,error}=await supabaseClient.rpc('decide_point_suggestion',{
    p_suggestion_id:id,
    p_decision:decision,
    p_decision_note:decisionNote
  });
  button.disabled=false;
  if(error){console.error(error);setAdminFeedback('Não foi possível registrar a decisão. '+(error.message||''),true);return;}
  if(data?.status==='duplicate'){
    const found=data.match||{};setAdminFeedback(`Este ponto já consta em ${found.category||'uma lista'} · ${found.work_group||'catálogo'}: “${found.title||'Ponto sem título'}”. A indicação permaneceu pendente.`,true);return;
  }
  setAdminFeedback(decision==='approved'?'Indicação aprovada e adicionada ao catálogo.':'Indicação rejeitada com justificativa registrada.');
  await Promise.all([loadPointSuggestions(),decision==='approved'?loadRemotePoints():Promise.resolve()]);
}
function normalizeCatalogText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('pt-BR');}
async function findExistingPoint(title,lyrics){
  const {data,error}=await supabaseClient.from('points').select('id,title,category,work_group,lyrics').eq('is_deleted',false).limit(1000);
  if(error)throw error;
  const candidateTitle=title||String(lyrics||'').split(/\r?\n/).find(line=>line.trim())?.slice(0,120)||'';
  const titleKey=normalizeCatalogText(candidateTitle),lyricsKey=normalizeCatalogText(lyrics);
  const catalog=new Map(points.map(point=>[point.id,{...point,work_group:point.group}]));
  for(const point of data||[])catalog.set(point.id,point);
  return [...catalog.values()].filter(point=>(titleKey&&normalizeCatalogText(point.title)===titleKey)||(lyricsKey&&normalizeCatalogText(point.lyrics)===lyricsKey));
}
async function submitPointSuggestion(event){
  event.preventDefault();const form=event.currentTarget,feedback=document.querySelector('#suggestion-feedback'),submit=document.querySelector('#suggestion-submit'),data=new FormData(form);
  if(String(data.get('website')||'').trim()){form.reset();refreshPointSuggestionCategories();feedback.textContent='Obrigado pela indicação. Se for aprovada pelos dirigentes da casa, incluiremos o ponto na lista correspondente.';return;}
  if(!supabaseClient){feedback.textContent='O envio está temporariamente indisponível. Tente novamente mais tarde.';return;}
  const group=String(data.get('work_group')||''),category=String(data.get('category')||''),name=String(data.get('name')||'').trim()||null,lyrics=String(data.get('lyrics')||'').trim(),youtubeUrl=String(data.get('youtube_url')||'').trim(),file=form.querySelector('#suggestion-voice').files?.[0]||null;
  if(!POINT_SUGGESTION_CATEGORIES[group]?.includes(category)){feedback.textContent='Escolha um grupo e uma categoria válidos.';return;}
  if(!lyrics||lyrics.length>15000){feedback.textContent='Informe a letra do ponto, com até 15.000 caracteres.';return;}
  if(youtubeUrl&&!getYouTubeId(youtubeUrl)){feedback.textContent='Informe um link válido do YouTube ou deixe o campo vazio.';return;}
  const allowedTypes=new Set(['audio/mpeg','audio/mp4','audio/x-m4a','audio/wav','audio/x-wav','audio/ogg','audio/webm','audio/aac']),extensionType={mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',ogg:'audio/ogg',webm:'audio/webm',aac:'audio/aac'};let contentType=file?.type?.toLowerCase()||'';
  if(file){if(file.size>15*1024*1024){feedback.textContent='A gravação deve ter no máximo 15 MB.';return;}if(!allowedTypes.has(contentType)){const extension=file.name.split('.').pop()?.toLowerCase()||'';contentType=extensionType[extension]||'';}if(!allowedTypes.has(contentType)){feedback.textContent='Envie uma gravação MP3, M4A, WAV, OGG, WEBM ou AAC.';return;}}
  submit.disabled=true;submit.textContent='Verificando o catálogo...';feedback.textContent='';
  let existing;try{existing=await findExistingPoint(name,lyrics);}catch(error){console.error(error);feedback.textContent='Não foi possível verificar o catálogo agora. Nenhuma indicação foi enviada; tente novamente.';submit.disabled=false;submit.textContent='Enviar indicação';return;}
  if(existing.length){feedback.innerHTML=`<span>Obrigado por querer contribuir! Encontramos ${existing.length===1?'este ponto':'pontos correspondentes'} já cadastrado${existing.length===1?'':'s'}:</span><ul>${existing.map(point=>`<li><strong>${esc(point.title)}</strong> — ${esc(point.category)} · ${esc(point.work_group)}</li>`).join('')}</ul><span>A indicação não foi enviada porque o ponto já está na lista.</span>`;submit.disabled=false;submit.textContent='Enviar indicação';return;}
  const submissionId=globalThis.crypto?.randomUUID?.();if(!submissionId){feedback.textContent='Este navegador não permite enviar agora. Abra a página atualizada e tente novamente.';submit.disabled=false;submit.textContent='Enviar indicação';return;}
  const voicePath=file?submissionId+'/voice':null;
  if(file){const uploaded=await supabaseClient.storage.from('point-suggestion-voice').upload(voicePath,file,{cacheControl:'3600',contentType,upsert:false});if(uploaded.error){console.error(uploaded.error);feedback.textContent='Não foi possível enviar a gravação. Tente novamente ou envie a indicação sem áudio.';submit.disabled=false;submit.textContent='Enviar indicação';return;}}
  const {error:insertError}=await supabaseClient.from('point_suggestions').insert({id:submissionId,name,category,work_group:group,lyrics,youtube_url:youtubeUrl||null,voice_path:voicePath});
  if(insertError){console.error(insertError);feedback.textContent='Não foi possível salvar a indicação. Tente novamente mais tarde.';submit.disabled=false;submit.textContent='Enviar indicação';return;}
  form.reset();refreshPointSuggestionCategories();feedback.textContent='Obrigado pela indicação! Se ela for aprovada pelos dirigentes da casa, incluiremos o ponto na lista correspondente.';submit.disabled=false;submit.textContent='Enviar indicação';if(isAdmin())loadPointSuggestions();
}
async function inviteTempleMember(event){event.preventDefault();if(!isAdmin()){setAdminFeedback('Entre como administrador para convidar alguém.',true);return;}const email=document.querySelector('#admin-invite-email').value.trim().toLowerCase();const button=document.querySelector('#admin-invite-submit');button.disabled=true;button.textContent='Enviando convite...';const {error}=await supabaseClient.functions.invoke('invite-temple-member',{body:{email}});button.disabled=false;button.textContent='Enviar convite';if(error){setAdminFeedback('Não foi possível enviar o convite. Confirme se a função de convites está implantada no Supabase e se o e-mail ainda não tem uma conta.',true);console.error(error);return;}document.querySelector('#admin-invite-form').reset();setAdminFeedback(`Convite enviado para ${email}. A pessoa poderá criar a própria senha pelo link recebido.`);}
async function init(){const config=window.TU7VD_SUPABASE_CONFIG||{};if(config.url&&config.anonKey&&window.supabase?.createClient){supabaseClient=window.supabase.createClient(config.url,config.anonKey);const {data}=await supabaseClient.auth.getSession();if(hasAdminAccess(data.session?.user))adminUser=data.session.user;else if(data.session)await supabaseClient.auth.signOut();supabaseClient.auth.onAuthStateChange((_event,session)=>{adminUser=hasAdminAccess(session?.user)?session.user:null;updateAdminPanel();});await loadRemotePoints();}else{document.querySelector('#admin-setup-message').hidden=false;document.querySelector('#admin-setup-message').textContent='Para ativar o acesso, configure a URL e a chave pública do Supabase em supabase-config.js e aplique o arquivo supabase/schema.sql ao projeto.';document.querySelector('#admin-login-form').hidden=true;}render();updateAdminPanel();const sharedPoint=new URL(location.href).searchParams.get('ponto');if(sharedPoint&&points.some(p=>p.id===sharedPoint))openPoint(sharedPoint);}
let pendingPointImport=[];
const importFileInput=document.querySelector('#import-points-file');
const importPanel=document.querySelector('#import-points-panel');
const importPreview=document.querySelector('#import-points-preview');
const importSaveButton=document.querySelector('#import-points-save');
function normalizeImportedLyrics(value=''){return String(value).replace(/\r\n?/g,'\n').split('\n').map(line=>line.trim()).join('\n').trim();}
function importKey(value=''){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').replace(/[^a-z0-9]+/g,' ').trim();}
function parsePointImport(text){
  const lines=String(text).replace(/^\uFEFF/,'').replace(/\r/g,'').split('\n');const records=[];let current=null;let readingLyrics=false;let foundMarkers=false;
  const save=()=>{if(current){current.lyrics=(current.lyrics||[]).join('\n').trim();records.push(current);current=null;}readingLyrics=false;};
  for(const raw of lines){const line=raw.trim();if(/^[-_=]{3,}$/.test(line)){save();continue;}
    const field=line.match(/^([^:]{2,30}):\s*(.*)$/);
    if(field){const key=importKey(field[1]);const value=field[2].trim();
      if(['ponto','nome','nome do ponto'].includes(key)){save();current={title:value,category:'',group:'',subtitle:'',source:'',videoUrl:'',audioUrl:'',lyrics:[]};foundMarkers=true;readingLyrics=false;continue;}
      if(current){
        if(key==='categoria'||key==='orixa'){current.category=value;readingLyrics=false;foundMarkers=true;continue;}
        if(key==='linha'){current.category=value;current.group='Linhas de trabalho';readingLyrics=false;foundMarkers=true;continue;}
        if(key==='subgrupo'){current.category=value;readingLyrics=false;foundMarkers=true;continue;}
        if(key==='grupo'){current.group=/ritual/i.test(value)?'Ritualística':/linha/i.test(value)?'Linhas de trabalho':'Orixás';readingLyrics=false;foundMarkers=true;continue;}
        if(key==='complemento'||key==='subtitulo'){current.subtitle=value;readingLyrics=false;foundMarkers=true;continue;}
        if(key==='fonte'||key==='referencia'){current.source=value;readingLyrics=false;foundMarkers=true;continue;}
        if(key==='video'||key==='video url'){current.videoUrl=value;readingLyrics=false;foundMarkers=true;continue;}
        if(key==='audio'||key==='audio url'){current.audioUrl=value;readingLyrics=false;foundMarkers=true;continue;}
        if(key==='letra'){if(value)current.lyrics.push(value);readingLyrics=true;foundMarkers=true;continue;}
      }
    }
    if(!current){if(!line)continue;current={title:line,category:'Importados',group:'Orixás',subtitle:'',source:'',videoUrl:'',audioUrl:'',lyrics:[]};readingLyrics=true;continue;}
    if(readingLyrics||line)current.lyrics.push(raw);
  }
  save();return records.filter(r=>r.title&&r.lyrics);
}
async function extractImportText(file){if(file.name.toLowerCase().endsWith('.txt'))return await file.text();if(!file.name.toLowerCase().endsWith('.docx'))throw new Error('Escolha um arquivo .txt ou .docx.');if(!window.JSZip)throw new Error('Leitor DOCX indisponível. Confira sua conexão e tente novamente.');const zip=await JSZip.loadAsync(file);const doc=zip.file('word/document.xml');if(!doc)throw new Error('O arquivo DOCX não contém um documento Word válido.');const xml=new DOMParser().parseFromString(await doc.async('text'),'application/xml');if(xml.querySelector('parsererror'))throw new Error('Não consegui ler este arquivo DOCX.');const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main';return [...xml.getElementsByTagNameNS(ns,'p')].map(p=>[...p.getElementsByTagNameNS(ns,'t')].map(t=>t.textContent||'').join('')).join('\n');}
function validImportSource(value){if(!value)return true;try{return ['http:','https:'].includes(new URL(value).protocol);}catch{return false;}}
function makePointImportPlan(records){const seen=new Set();return records.map((record,index)=>{if(!validImportSource(record.source)||!validImportSource(record.videoUrl)||!validImportSource(record.audioUrl))return {record,status:'invalid'};const fileKey=importKey(record.title)+'|'+importKey(record.category||'');if(seen.has(fileKey))return {record,status:'file-duplicate'};seen.add(fileKey);const sameTitle=points.filter(p=>importKey(p.title)===importKey(record.title));let matches=record.category?sameTitle.filter(p=>importKey(p.category)===importKey(record.category)):sameTitle;if(!matches.length&&sameTitle.length===1)matches=sameTitle;if(matches.length>1)return {record,status:'ambiguous'};const existing=matches[0];if(!existing){const slug=importKey(record.title).replace(/ /g,'-').slice(0,54)||'ponto';return {record,status:'new',point:{id:`import-${slug}-${Date.now().toString(36)}-${index}`,title:record.title,category:record.category||'Importados',group:record.group||'Orix\u00e1s',subtitle:record.subtitle,source:record.source||SOURCE,lyrics:record.lyrics,videoUrl:record.videoUrl||'',audioUrl:record.audioUrl||''}};}const point={...existing,title:record.title,category:record.category||existing.category,group:record.group||existing.group,subtitle:record.subtitle||existing.subtitle||'',source:record.source||existing.source||SOURCE,lyrics:record.lyrics,videoUrl:record.videoUrl||existing.videoUrl||'',audioUrl:record.audioUrl||existing.audioUrl||''};const same=normalizeImportedLyrics(existing.lyrics||'')===normalizeImportedLyrics(record.lyrics);const metadataSame=existing.title===point.title&&existing.category===point.category&&existing.group===point.group&&existing.subtitle===point.subtitle&&existing.source===point.source&&existing.videoUrl===point.videoUrl&&existing.audioUrl===point.audioUrl;const status=same?(metadataSame?'same':'metadata'):existing.lyrics?'replace':'fill';return {record,existing,status,point};});}
function showImportPreview(){
  const labels={new:'Ponto novo',fill:'Letra será cadastrada',replace:'Letra será atualizada',metadata:'Letra igual; outros dados atualizados',same:'Já existe com a mesma letra',ambiguous:'Nome repetido em mais de uma categoria; revise manualmente.',invalid:'Fonte inválida; use um link http ou https.', 'file-duplicate':'Ponto duplicado no arquivo; remova uma ocorrência.'};
  importPreview.innerHTML='<p><b>'+pendingPointImport.length+' ponto(s) reconhecido(s)</b></p>'+pendingPointImport.map((item,index)=>{
    const media=item.status==='new'?'<div class="import-media-links"><a href="https://pontos-cantados.tueg.pt/" target="_blank" rel="noopener">Consultar catálogo de pontos do TUEG</a><small>Confira a gravação e informe um endereço direto de áudio, quando disponível.</small><label>URL direta do áudio (opcional)<input type="url" data-audio-index="'+index+'" value="'+esc(item.point.audioUrl||'')+'" placeholder="https://.../audio.mp3"></label></div>':'';
    return '<article class="import-preview-item"><strong>'+esc(item.record.title)+'</strong><span>'+esc(item.record.category||'Importados')+' &middot; '+esc(labels[item.status])+'</span>'+media+'</article>';
  }).join('');
  const writable=pendingPointImport.some(item=>['new','fill','replace','metadata'].includes(item.status));const blocked=pendingPointImport.some(item=>['ambiguous','invalid','file-duplicate'].includes(item.status));
  importSaveButton.disabled=!writable||blocked;importSaveButton.textContent=blocked?'Corrija os itens sinalizados':'Confirmar importação';
}async function handleImportFile(){const file=importFileInput.files?.[0];if(!file)return;importPanel.hidden=false;importPreview.textContent='Lendo arquivo...';importSaveButton.disabled=true;try{const text=await extractImportText(file);const records=parsePointImport(text);if(!records.length)throw new Error('Não encontrei ponto com título e letra. Use “Ponto:” e “Letra:” ou título na primeira linha.');pendingPointImport=makePointImportPlan(records);showImportPreview();}catch(error){pendingPointImport=[];importPreview.textContent=error.message||'Não foi possível ler o arquivo.';}}
async function savePointImport(){if(!isAdmin()){setAdminFeedback('Entre como administrador para importar.',true);return;}const changes=pendingPointImport.filter(item=>['new','fill','replace','metadata'].includes(item.status)&&!item.reviewSubmitted);if(!changes.length)return;for(const item of pendingPointImport){if(item.status!=='new'||item.reviewSubmitted)continue;const i=pendingPointImport.indexOf(item);const video=document.querySelector('[data-video-index="'+i+'"]')?.value.trim()||'';const audio=document.querySelector('[data-audio-index="'+i+'"]')?.value.trim()||'';if(!validImportSource(video)||!validImportSource(audio)){setAdminFeedback('Os links de vídeo e áudio precisam começar com http:// ou https://.',true);return;}if(audio&&/(youtube\.com|youtu\.be|spotify\.com)/i.test(audio)){setAdminFeedback('Para reprodução na página, informe um endereço direto de áudio; links do YouTube e Spotify não são compatíveis.',true);return;}item.point.videoUrl=video;item.point.audioUrl=audio;}importSaveButton.disabled=true;importSaveButton.textContent='Enviando para revisão...';for(const item of changes){const p=item.point;if(item.status!=='new'&&!PointTextReview.changedText(item.existing||{},p)){const {error}=await supabaseClient.rpc('update_point_metadata',{p_point_id:p.id,p_category:p.category,p_work_group:p.group,p_source:p.source||SOURCE,p_video_url:p.videoUrl||'',p_audio_url:p.audioUrl||''});if(error){importPreview.insertAdjacentHTML('beforeend',`<p class="import-error">Não foi possível salvar os dados de “${esc(p.title)}”. ${esc(error.message||'Verifique a conexão e as permissões.')}</p>`);importSaveButton.disabled=false;importSaveButton.textContent='Tentar novamente';return;}item.reviewSubmitted=true;continue;}const proposed={id:p.id,title:p.title,category:p.category,work_group:p.group,subtitle:p.subtitle||'',source:p.source||SOURCE,lyrics:p.lyrics||'',video_url:p.videoUrl||'',audio_url:p.audioUrl||''};const suggestions=['title','subtitle','lyrics'].flatMap(field=>PointTextReview.inspect(p[field]).map(entry=>({...entry,field})));const {error}=await supabaseClient.rpc('submit_point_text_review',{p_point_id:p.id,p_proposed_content:proposed,p_suggestions:suggestions});if(error){importPreview.insertAdjacentHTML('beforeend',`<p class="import-error">Não foi possível enviar “${esc(p.title)}” para revisão. ${esc(error.message||'Verifique a conexão e as permissões.')}</p>`);importSaveButton.disabled=false;importSaveButton.textContent='Tentar novamente';return;}item.reviewSubmitted=true;}await loadPointReviewHistory();render();populateAdminSelect();setAdminFeedback(`${changes.length} ponto(s) enviado(s) para revisão; o catálogo atual permanece publicado até a aprovação.`);pendingPointImport=[];importPanel.hidden=true;importPreview.innerHTML='';importFileInput.value='';}
function cancelPointImport(){pendingPointImport=[];importPanel.hidden=true;importPreview.innerHTML='';importFileInput.value='';importSaveButton.disabled=true;}
